class Statement { constructor(db, sql, params = []) { this.db = db; this.sql = sql; this.params = params; } bind(...params) { return new Statement(this.db, this.sql, params); } execute() { const statement = this.db.prepare(this.sql); if (statement.columns().length) return { success: true, results: statement.all(...this.params), meta: { changes: this.db.prepare("SELECT changes() value").get().value } }; const result = statement.run(...this.params); return { success: true, results: [], meta: { changes: Number(result.changes) } }; } async all() { return this.execute(); } async run() { return this.execute(); } async raw() { const statement = this.db.prepare(this.sql); statement.setReturnArrays(true); return statement.all(...this.params); } }
class D1 { constructor(db) { this.db = db; } prepare(sql) { return new Statement(this.db, sql); } async batch(statements) { this.db.exec("BEGIN IMMEDIATE"); try { const result = statements.map((item,index) => {try{return item.execute();}catch(error){error.message=`batch[${index}] ${item.sql}: ${error.message}`;throw error;}}); this.db.exec("COMMIT"); return result; } catch (error) { if (this.db.isTransaction) this.db.exec("ROLLBACK"); throw error; } } }
